package com.example.assets_management.security.auth; import com.example.assets_management.employee.entity.Employee; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="refresh_tokens",indexes=@Index(name="idx_refresh_tokens_user",columnList="user_id")) @Getter @Setter @NoArgsConstructor public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private Employee user; @Column(name="token_hash",nullable=false,unique=true,length=128) private String tokenHash; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="revoked_at") private Instant revokedAt; @Column(name="replaced_by_hash",length=128) private String replacedByHash; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public boolean isActive(){return revokedAt==null&&expiresAt.isAfter(Instant.now());} }
